// Generates the client from the committed contract into src/generated.
// Never edit src/generated by hand: run `pnpm --filter @caltodo/api-client
// run generate` after a change to contract/openapi.json.
//
// The generator deletes and writes its whole output directory. Other tasks
// of the checkout (the type check, Oxlint, Vitest, contract:check) can read
// src/generated at the same time (STACK.md §3), so the generator writes into
// a scratch directory first. Then only a changed file is replaced, with an
// atomic rename, and a file that the generator no longer produces is deleted.
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  writeFileSync,
} from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join, relative, sep } from "node:path"
import process from "node:process"
import { URL, fileURLToPath } from "node:url"
import { createClient } from "@hey-api/openapi-ts"
import { generatorConfig } from "./generator-config.mjs"

const root = new URL("../../../", import.meta.url)
const target = fileURLToPath(new URL("packages/api-client/src/generated", root))

const listFiles = (dir) => {
  if (!existsSync(dir)) return []
  return readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) =>
      relative(dir, join(entry.parentPath, entry.name)).split(sep).join("/"),
    )
}

const scratch = mkdtempSync(join(tmpdir(), "caltodo-generate-"))
try {
  const output = join(scratch, "generated")
  await createClient(
    generatorConfig({
      input: fileURLToPath(new URL("contract/openapi.json", root)),
      output,
    }),
  )
  const produced = new Set(listFiles(output))
  for (const file of produced) {
    const next = readFileSync(join(output, file))
    const path = join(target, file)
    if (existsSync(path) && readFileSync(path).equals(next)) continue
    mkdirSync(dirname(path), { recursive: true })
    const temporary = `${path}.${String(process.pid)}.tmp`
    writeFileSync(temporary, next)
    renameSync(temporary, path)
  }
  for (const file of listFiles(target)) {
    if (!produced.has(file)) rmSync(join(target, file))
  }
} finally {
  rmSync(scratch, { recursive: true, force: true })
}
